# counting.map — the loop is the counter (issues 307, 312)
#
# A box cannot remember, so the count rides a wire that points backwards:
# add one, say it, and if it is still below ten send it round again. The
# old design refused any map with a loop in it; this one could not count
# without one. Ten lines come out, 1 to 10, in order — only one value is
# ever in flight, and the loop is what carries it. The final 10 leaves by
# the "equal" exit and is held as the program's result 0.
#
# The saying sits on the loop's own path (tell passes the number on). A
# report fanned out beside the loop would run at the same time as the next
# step and its lines could come out of order.

boxes = ../boxes/

station start (boxes/062-arithmetic.c:constant)
  in 0 = 0
  out 0 - add_one.0

station add_one (boxes/062-arithmetic.c:increment)
  in 0 - start.0
  in 0 - below_ten.0
  out 0 - tell.0

station tell (boxes/064-launch.c:echo)
  in 0 - add_one.0
  out 0 - below_ten.0

comparator below_ten (boxes/062-arithmetic.c:below)
  in 0 - tell.0
  in 1 = 10
  out 0 - add_one.0
  out 1 - 0$
